let cloudLoadId=0,cloudLoadingUserId=null;
async function refreshPhotoUrls(){
  if(!cloudEnabled)return;
  await Promise.all(data.inspiration.filter(x=>x.storagePath).map(async item=>{
    try{await cloudStore.signedPhotoUrl(item.storagePath)}catch{ /* Keep the private photo hidden on failure. */ }
  }));
}
async function loadCloudAccount(user){
  if(cloudLoadingUserId===user.id)return;
  cloudLoadingUserId=user.id;
  const id=++cloudLoadId;
  cloudReady=false;render();
  try{
    const document=await cloudStore.load(user);
    if(id!==cloudLoadId)return;
    cloudAccount=user;cloudHasDocument=Boolean(document);data=document||seed();data.financialGoals??=[];data.profile.orientation??={};
    if(pendingTheme!==null){data.profile.theme=pendingTheme;if(document)save()}
    flowerIndex=Math.max(0,Math.min(5,Number(data.profile.theme)||0));
    await refreshPhotoUrls();
    cloudMessage='';cloudReady=true;render();
  }catch(error){
    if(id!==cloudLoadId)return;
    cloudAccount=null;cloudReady=true;
    cloudMessage='Не получилось открыть данные в Supabase. Проверь подключение проекта и попробуй снова.';
    render();
  }finally{if(cloudLoadingUserId===user.id)cloudLoadingUserId=null}
}
async function bootCloud(){
  if(!cloudEnabled)return;
  cloudClient.auth.onAuthStateChange((event,session)=>{
    if(event==='SIGNED_OUT'){
      cloudLoadId++;cloudLoadingUserId=null;cloudStore.load(null).catch(()=>{});cloudAccount=null;cloudReady=true;cloudHasDocument=false;data=seed();render();
    }else if(event==='SIGNED_IN'&&session?.user?.id!==cloudAccount?.id){
      setTimeout(()=>loadCloudAccount(session.user),0);
    }
  });
  try{
    const {data:result,error}=await cloudClient.auth.getUser();
    if(error&&!result?.user)throw error;
    if(result?.user)await loadCloudAccount(result.user);
    else{cloudReady=true;render()}
  }catch{cloudReady=true;render()}
}
async function importLegacy(){
  if(!cloudEnabled||!cloudAccount||!legacyData||cloudHasDocument)return;
  const copy=JSON.parse(JSON.stringify(legacyData)),uploaded=[];
  cloudReady=false;render();
  try{
    for(const item of copy.inspiration||[]){
      if(item.type!=='photo'||!item.src?.startsWith('data:image/'))continue;
      const blob=await (await fetch(item.src)).blob();
      const path=await cloudStore.uploadPhoto(blob,item.id);
      uploaded.push(path);item.storagePath=path;delete item.src;
    }
    data=copy;data.financialGoals??=[];data.profile.orientation??={};if(pendingTheme!==null)data.profile.theme=pendingTheme;
    if(!save())throw Error('Не удалось начать сохранение');
    await cloudStore.pending;if(cloudStore.failed)throw Error('Не удалось сохранить данные в аккаунте');
    localStorage.removeItem(KEY);legacyData=null;cloudHasDocument=true;
    await refreshPhotoUrls();cloudMessage='';cloudReady=true;render();toast('Записи теперь в твоём аккаунте');
  }catch(error){
    await Promise.all(uploaded.map(path=>cloudStore.removePhoto(path).catch(()=>{})));
    data=seed();cloudReady=true;cloudMessage='Перенос не завершился. Старая копия осталась в браузере.';
    render();toast(cloudMessage);
  }
}
async function startFresh(){
 if(!cloudEnabled||!cloudAccount)return;
 data=seed();if(pendingTheme!==null)data.profile.theme=pendingTheme;cloudReady=false;render();
 if(!save()){cloudReady=true;render();toast('Не получилось начать. Проверь подключение.');return}
 try{await cloudStore.pending;if(cloudStore.failed)throw Error('Не удалось сохранить');cloudHasDocument=true;cloudReady=true;render()}
 catch{cloudReady=true;render();toast('Не получилось сохранить начало в аккаунте.')}
}
async function signOut(){
  if(!cloudEnabled)return;
  if(cloudStore.failed){toast('Сначала скачай копию несохранённых данных.');return}
  try{await cloudStore.pending;if(cloudStore.failed){toast('Сначала скачай копию несохранённых данных.');return}await cloudClient.auth.signOut()}catch{toast('Не получилось выйти. Попробуй ещё раз.')}
}
